# ---- questions: Gemini's free tier first (with Google Search), Claude as the backup ---------------------------

ASK_ENGINES = [x.strip().lower() for x in env("ASK_ENGINES", "groq,gemini,claude").split(",") if x.strip()]


GEMINI_FALLBACK_MODELS = ("gemini-flash-latest", "gemini-2.5-flash", "gemini-2.0-flash")


def gemini_models() -> list[str]:
    """The configured model first, then stable names, so a renamed model doesn't break answers."""
    return list(dict.fromkeys([GEMINI_MODEL, *GEMINI_FALLBACK_MODELS]))


ASK_LAST_ERROR: dict = {"text": None}


def ask_error_hint(exc: Optional[BaseException]) -> str:
    """A short, safe reason for a failed answer (never the key)."""
    t = str(exc or "")
    if "429" in t or "quota" in t.lower() or "exhausted" in t.lower():
        return "Gemini's free limit is used up for now"
    if "401" in t or "403" in t or "API key" in t:
        return "the Gemini key on Railway was refused"
    if "none of the model names" in t:
        return "Gemini doesn't recognise the model name (GEMINI_MODEL)"
    if "no question engine" in t:
        return "no AI key is set on Railway"
    if "timed out" in t.lower():
        return "Gemini took too long to answer"
    if re.search(r"HTTP 5\d\d", t):
        return "Gemini is overloaded on Google's side; try again in a minute"
    if "came back empty" in t:
        return "Gemini came back with no text"
    code = re.search(r"HTTP (\d{3})", t)
    return f"error {code.group(1)}: {ask_error_snip(t)}" if code else f"didn't answer: {ask_error_snip(t)}"


def ask_error_snip(t: str) -> str:
    """A short piece of an error to show in Discord, with anything key-like blanked out."""
    t = re.sub(r"(AIza[\w-]{10,}|sk-[\w-]{10,}|key=[^&\s]+)", "[key]", str(t or ""))
    t = re.sub(r"^(?:Gemini|Groq) HTTP \d{3}:\s*", "", t)
    m = re.search(r"['\"]message['\"]\s*:\s*['\"]([^'\"]{4,})", t)
    return clip(" ".join((m.group(1) if m else t).split()), 90) or type(t).__name__


def claude_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    low = t.lower()
    if "credit balance" in low or "billing" in low:
        return "the Claude account is out of credits"
    if "authentication" in low or "401" in t or "invalid x-api-key" in low:
        return "the Claude key on Railway was refused"
    if "overloaded" in low or "529" in t or "rate_limit" in low or "429" in t:
        return "Claude is busy; try again in a minute"
    return f"didn't answer: {ask_error_snip(t)}"


XAI_API_KEY = env("XAI_API_KEY", "")
XAI_MODEL = env("XAI_MODEL", "grok-3")


def xai_key() -> str:
    """The xAI key with line breaks and spaces removed, so a wrapped paste still sends as one token."""
    return "".join((XAI_API_KEY or "").split())


def xai_ready() -> bool:
    """A real xAI key starts with xai-. A model name such as grok-3 in that variable is not a key."""
    key = xai_key()
    return key.startswith("xai-") and len(key) > 20


def ask_enabled() -> bool:
    """Can the bot answer questions at all (a Gemini or a Claude key)?"""
    if xai_ready() or env("OPENROUTER_API_KEY", ""):
        return True
    return any((e == "groq" and GROQ_API_KEY) or (e == "gemini" and GEMINI_API_KEY) or (e == "claude" and ai_enabled())
               for e in ASK_ENGINES)


def groq_models(search: bool) -> list[tuple[str, bool]]:
    """[(model, search the web?)]: the main model first, then the fallbacks."""
    return [(m, search and m in GROQ_SEARCH_OK) for m in dict.fromkeys([GROQ_MODEL, *GROQ_FALLBACK_MODELS])]


async def ask_groq(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Groq's free tier. A model that's busy or out of free uses hands off to the next."""
    import aiohttp
    errors = []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=18 if search else 8)) as session:
        for model, web in groq_models(search):
            body = {"model": model, "temperature": 0.4, "max_completion_tokens": 4096,
                    "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
            if model.startswith("openai/gpt-oss"):
                body["reasoning_effort"] = "low"
            if web:
                body.update(tools=[{"type": "browser_search"}], tool_choice="auto")
            data, tried_plain = None, False
            while True:
                try:
                    async with session.post("https://api.groq.com/openai/v1/chat/completions", json=body,
                                            headers={"Authorization": f"Bearer {GROQ_API_KEY}"}) as resp:
                        if resp.status == 400 and "tools" in body and not tried_plain:
                            body = {k: v for k, v in body.items() if k not in ("tools", "tool_choice")}
                            tried_plain = True                          # search not allowed here: answer without it
                            continue
                        if resp.status != 200:
                            err = f"Groq HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403):
                                raise RuntimeError(err)                 # a bad key fails on every model
                            errors.append(err)
                            break
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:
                    errors.append(f"Groq timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            msg = ((data.get("choices") or [{}])[0].get("message") or {})
            text = re.sub(r"<think>.*?</think>", "", msg.get("content") or "", flags=re.S)
            text = re.sub(r"【[^】]{0,40}】", "", text).strip()               # browser_search citation marks
            if text:
                sources = []
                for tool in msg.get("executed_tools") or []:
                    for r in ((tool.get("search_results") or {}).get("results") or []):
                        u = str(r.get("url") or "").strip()
                        if u.startswith("https://") and u not in sources:
                            sources.append(u)
                return text, sources[:3]
            errors.append(f"Groq came back empty on {model}")
    log.warning("Groq tried %s: %s", ", ".join(m for m, _ in groq_models(search)), " | ".join(errors)[:600])
    raise RuntimeError(" | ".join(errors) or "Groq came back empty")


def groq_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    if "429" in t:
        return "Groq's free limit is used up for now"
    if "401" in t or "403" in t:
        return "the Groq key on Railway was refused"
    if "timed out" in t:
        return "Groq took too long"
    if re.search(r"HTTP 5\d\d", t):
        return "Groq is busy; try again in a minute"
    return "Groq didn't answer: " + ask_error_snip(t)


async def ask_gemini(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Gemini, searching Google for anything current. The key goes in a header."""
    import aiohttp
    system = (system + "\n\nYou don't have a group_stats tool here: for the group's own records use only the group "
              "data included in the message, and say so if it isn't there.")
    body = {"system_instruction": {"parts": [{"text": system}]},
            "contents": [{"role": "user", "parts": [{"text": user_text}]}],
            "tools": [{"google_search": {}}],
            "generationConfig": {"temperature": 0.4, "maxOutputTokens": 8192}}
    if not search:
        body.pop("tools")                                      # the numbers are in the message: save the search quota
    data, text, errors = None, "", []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=18 if search else 8)) as session:
        for model in gemini_models():
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
            mbody, tried_plain, data = body, False, None
            while True:
                try:
                    async with session.post(url, json=mbody, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
                        if resp.status == 400 and not tried_plain and "tools" in mbody:
                            mbody = {k: v for k, v in mbody.items() if k != "tools"}   # no search on this model
                            tried_plain = True
                            continue
                        if resp.status == 404:
                            errors.append(f"{model} not found")
                            break                                               # unknown model: try the next
                        if resp.status != 200:
                            err = f"Gemini HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403) or "API key" in err:
                                raise RuntimeError(err)                         # a bad key fails on every model
                            errors.append(err)
                            break                                               # busy / limit hit: next model
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:                                        # timeout, connection dropped
                    errors.append(f"Gemini timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            if not data.get("candidates") and (data.get("promptFeedback") or {}).get("blockReason"):
                return "", []                                                   # blocked: the fallback decides
            cand = (data.get("candidates") or [{}])[0]
            text = "".join(p.get("text", "") for p in ((cand.get("content") or {}).get("parts") or [])
                           if not p.get("thought")).strip()
            if text:
                break
            errors.append(f"Gemini came back empty on {model} ({cand.get('finishReason') or 'no reason given'})")
    if not text:
        if errors and all(e.endswith("not found") for e in errors):
            raise RuntimeError("Gemini: none of the model names worked (check GEMINI_MODEL)")
        log.warning("Gemini tried %s: %s", ", ".join(gemini_models()), " | ".join(errors)[:600])
        raise RuntimeError(" | ".join(e for e in errors if not e.endswith("not found")) or "Gemini came back empty")
    sources = []
    for ch in ((cand.get("groundingMetadata") or {}).get("groundingChunks") or []):
        uri = ((ch.get("web") or {}).get("uri") or "").strip()
        if uri.startswith("https://") and uri not in sources:
            sources.append(uri)
    return text, sources[:3]


_NO_ANSWER = re.compile(r"\b(i (?:couldn'?t|could not|can'?t|cannot|wasn'?t able to|was unable to|don'?t have|do not have)"
                        r" (?:find|access|confirm|verify|browse|search|look up|get|provide|give)|unable to (?:find|access|"
                        r"confirm|verify)|no (?:recent |current |reliable )?(?:information|info|results|data) (?:on|about|for|"
                        r"available)|my knowledge cutoff|as of my last (?:update|training)"
                        r"|i(?:'m| am) (?:not able|unable) to (?:find|access|confirm|verify|browse|search|look up|get)"
                        r"|(?:don'?t|do not) have (?:real[- ]time|live|current|up[- ]to[- ]date|recent) (?:access|data|info|"
                        r"information|stats|results)|couldn'?t locate|there (?:is|was|are) no (?:recent |current |reliable )?"
                        r"(?:information|info|data|news|reports?)\b)", re.I)


def ask_unanswered(answer: str) -> bool:
    """Did the answer duck the question (empty, a few words, or 'I couldn't find...')?"""
    a = (answer or "").strip()
    m = _NO_ANSWER.search(a[:400])
    return len(a) < 20 or bool(m and (m.start() < 120 or len(a) < 200))   # a late hedge in a real answer is fine


async def ask_chat(url: str, key: str, model: str, system: str, user_text: str, label: str) -> tuple[str, list[str]]:
    """One OpenAI-style chat call. Returns (answer, no source links)."""
    import aiohttp
    body = {"model": model, "temperature": 0.4, "max_tokens": 900,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=60)) as session:
        async with session.post(url, json=body, headers={"Authorization": f"Bearer {key}"}) as resp:
            if resp.status != 200:
                raise RuntimeError(f"{label} HTTP {resp.status}: {(await resp.text())[:200]}")
            data = await resp.json(content_type=None)
    text = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "").strip()
    if not text:
        raise RuntimeError(f"{label} came back empty")
    return text, []


async def ask_xai(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Grok, from xAI, when XAI_API_KEY is set on the host. Cursor does not expose a chat API for this."""
    return await ask_chat("https://api.x.ai/v1/chat/completions", xai_key(), XAI_MODEL, system, user_text, "Grok")


async def ask_openrouter(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Grok through OpenRouter when OPENROUTER_API_KEY is set. OPENROUTER_MODEL can pick another model."""
    key = env("OPENROUTER_API_KEY", "")
    model = env("OPENROUTER_MODEL", "x-ai/grok-4-fast")
    return await ask_chat("https://openrouter.ai/api/v1/chat/completions", key, model, system, user_text, "OpenRouter")


async def ask_any(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Answer with Gemini (free) first. Claude is the fail-safe: it only runs when Gemini errors out or comes back
    without a real answer (and a Claude key is set). ASK_ENGINES can change the order.
    A Grok key (XAI_API_KEY, or OpenRouter) answers first when it is set."""
    last: Optional[Exception] = None
    fallback: Optional[tuple[str, list[str]]] = None
    why: list[str] = []
    ASK_LAST_ERROR["text"] = None
    engines = list(ASK_ENGINES)
    if xai_ready() and "xai" not in engines:
        engines.insert(0, "xai")
    elif env("OPENROUTER_API_KEY", "") and "openrouter" not in engines:
        engines.insert(0, "openrouter")
    for engine in engines:
        if engine == "xai" and xai_ready():
            try:
                answer, sources = await ask_xai(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_xai")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append("Grok: " + ask_error_snip(str(exc)))
                log.warning("Grok answer failed: %s", str(exc)[:300])
        elif engine == "openrouter" and env("OPENROUTER_API_KEY", ""):
            try:
                answer, sources = await ask_openrouter(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_openrouter")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append("OpenRouter: " + ask_error_snip(str(exc)))
                log.warning("OpenRouter answer failed: %s", str(exc)[:300])
        elif engine == "groq" and GROQ_API_KEY:
            try:
                answer, sources = await ask_groq(system, user_text, search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_groq")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                why.append(groq_error_hint(exc))
                log.warning("Groq answer failed: %s", str(exc)[:300])
        elif engine == "gemini" and GEMINI_API_KEY:
            try:
                answer, sources = await ask_gemini(system, user_text, search=search)
                if answer and not ask_unanswered(answer):
                    free_count("ask_gemini")
                    return answer, sources
                if answer:
                    fallback = (answer, sources)       # keep it in case nothing better comes
                else:
                    why.append("Gemini: it blocked or skipped the request")
            except Exception as exc:
                last = exc
                h = ask_error_hint(exc)
                why.append(h if "Gemini" in h else "Gemini: " + h)
                log.warning("Gemini answer failed: %s", str(exc)[:300])
        elif engine == "claude" and ai_enabled() and claude_budget_ok(essential=True) and claude_alive():
            try:
                answer, sources = await ask_claude(system, user_text)
            except Exception as exc:
                last = exc
                why.append("Claude backup: " + claude_error_hint(exc))
                log.warning("Claude answer failed: %s", str(exc)[:300])
                continue
            if answer:
                free_count("ask_claude")
                return answer, sources
    if fallback is not None:
        free_count("ask_gemini")
        return fallback
    ASK_LAST_ERROR["text"] = "; ".join(why) if why else ask_error_hint(last or RuntimeError("no question engine is set up"))
    raise last or RuntimeError("no question engine is set up")


# ==========================================================================
# r24: /live as a big, easy-to-read picture with a pace graph per leg, and /gamecard on demand.
# ==========================================================================

LV2_GAMES = 4                 # games drawn on one /live picture
LV2_ROWS = 7                  # legs drawn per game
# (periods, minutes per period) for working out how much of a game is gone
LV2_CLOCK = {"basketball/nba": (4, 12), "basketball/wnba": (4, 10), "basketball/mens-college-basketball": (2, 20),
             "football/nfl": (4, 15), "football/college-football": (4, 15), "hockey/nhl": (3, 20)}


def lv2_elapsed(ev: dict, path: Optional[str]) -> Optional[float]:
    """How much of the game has been played (0-1), from the period and clock; None when it can't tell."""
    if not ev or ev.get("state") != "in":
        return 1.0 if ev and (ev.get("final") or ev.get("state") == "post") else None
    detail = (ev.get("detail") or "").lower()
    fam = (path or "").split("/")[0]
    if fam == "soccer":
        m = re.search(r"(\d{1,3})(?:\+\d+)?'", detail)
        if m:
            return min(1.0, int(m.group(1)) / 90)
        if re.search(r"\b(ft|aet|full[- ]?time|pens?)\b", detail):
            return 1.0
        return 0.5 if re.search(r"\bht\b|half", detail) else None
    if fam == "baseball":
        m = re.search(r"(top|bot|bottom|mid|middle|end)\w*\s+(?:of\s+)?(\d{1,2})", detail)
        if not m:
            return None
        inning = int(m.group(2))
        half = {"top": 0.0, "mid": 0.5, "middle": 0.5, "bot": 0.5, "bottom": 0.5, "end": 1.0}[m.group(1)]
        return max(0.0, min(1.0, (inning - 1 + half) / 9))
    spec = LV2_CLOCK.get(path or "")
    if not spec:
        return None
    periods, mins = spec
    if "halftime" in detail or detail.strip() in ("half", "ht"):
        return 0.5
    if re.search(r"\b\d?ot\b", detail) and not ev.get("period"):
        return 1.0                             # "OT", "2OT" without a period number
    period = int(ev.get("period") or 0)
    if not period:
        m = re.search(r"\b[qp](\d)\b|(\d)(?:st|nd|rd|th)\b", detail)
        period = int(m.group(1) or m.group(2)) if m else 0
    if not period:
        return None
    if period > periods or "ot" in detail.split():
        return 1.0
    m = re.search(r"(\d{1,2}):(\d{2})", detail)
    left = (int(m.group(1)) + int(m.group(2)) / 60) if m else (
        0.0 if ("end" in detail or "intermission" in detail) else mins / 2)
    return max(0.0, min(1.0, ((period - 1) * mins + (mins - min(left, mins))) / (periods * mins)))


def lv2_pace(value: float, line: float, elapsed: Optional[float], text: str) -> Optional[float]:
    """Where this stat is headed if it keeps this rate (None early in a game, or for 'longest' stats)."""
    if elapsed is None or elapsed < 0.12 or elapsed >= 0.999 or re.search(r"longest|first|anytime", text, re.I):
        return None
    return round(value / elapsed, 1)


def lv2_game_rows(g: dict, show_open_only: bool = True) -> list[dict]:
    rows = [lv_row(r["s"], r["e"]) for r in g["rows"]
            if r["s"]["p"]["status"] == "open" or r["e"].get("status") != "open" or not show_open_only]
    return sorted(rows, key=lambda r: (LV_ORDER.get(r["state"], 9), r["who"].lower()))


async def lv2_board_data(client, gid: int, scope: str, uid: int, private: bool, now: datetime,
                         snap: list[dict]) -> Optional[dict]:
    """Everything the /live picture needs (avatars fetched here, before the render thread). None if nothing is live."""
    mine = [s for s in snap if lv_visible(s, scope, uid, private)]
    games = [g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in" and not g["ev"].get("final")]
    games.sort(key=lambda g: (event_time(g["ev"]) or now, g["id"]))
    out, uids = [], set()
    for g in games:
        rows = lv2_game_rows(g)
        if not rows:
            continue
        el = lv2_elapsed(g["ev"], g["path"])
        for r in rows:
            n = r.get("num")
            r["pace"] = lv2_pace(n["value"], n["line"], el, r["text"]) if n and r["state"] not in ("cleared", "dead") else None
            if r.get("uid"):
                uids.add(r["uid"])
        away, home = (dict(t) for t in lv_sides(g["ev"]))
        await lv2_attach_logos(away, home)
        ac = lv_team_colour(away)
        out.append({"league": LEAGUE_NAMES.get(g["path"] or "", ""), "away": dict(away, colour=ac),
                    "home": dict(home, colour=lv_team_colour(home, avoid=ac)), "status": lv_status_text(g["ev"]),
                    "elapsed": el, "rows": rows})
        if len(out) >= LV2_GAMES:
            break
    if not out:
        return None
    avatars = {}
    for u in list(uids)[:24]:
        user = await known_user(client, u)
        avatars[u] = await avatar_bytes(user) if user is not None else None
    heads = await design_rows_heads([r for g in out for r in g["rows"]])
    tonight = [(lv_clock(t), name, n) for t, name, n in lv_tonight(mine, now)]
    more = max(0, len([g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in"]) - len(out))
    return {"title": "LIVE NOW", "who": "everyone" if scope == "a" else "just you" if private else "mine",
            "updated": lv_clock(now), "games": out, "tonight": tonight, "avatars": avatars, "more_games": more,
            "heads": heads}


def _lv2_pace_bar(d, x: int, y: int, w: int, h: int, value: float, line: float, pace: Optional[float], side: str,
                  state: str) -> None:
    """The graph: a filled bar for now, a ghost bar for where it's headed, and a white tick at the line."""
    top = max(line * 1.5, value, pace or 0, 1)
    sx = lambda v: x + w * min(1.0, max(0.0, v / top))
    d.rounded_rectangle((x, y, x + w, y + h), h // 2, fill=(44, 44, 58))
    good = (value > line) if side == "over" else (value <= line)
    col = {"cleared": ART_GREEN, "dead": ART_RED, "close": ART_AMBER}.get(state) or (ART_GREEN if good and side == "over"
                                                                                     else ART_BLUE)
    if side == "under":
        col = ART_RED if value > line else (ART_AMBER if state == "close" else ART_GREEN)
    if pace is not None and pace > value:
        on = (pace > line) if side == "over" else (pace <= line)
        ghost = _brand_mix(ART_GREEN if on else ART_RED, (44, 44, 58), 0.55)
        d.rounded_rectangle((x, y, sx(pace), y + h), h // 2, fill=ghost)
    if value > 0:
        d.rounded_rectangle((x, y, max(x + h, sx(value)), y + h), h // 2, fill=col)
    lx = sx(line)
    d.rectangle((lx - 2, y - 7, lx + 2, y + h + 7), fill=(255, 255, 255))


async def lv2_live_payload(client, gid: int, scope: str, uid: int, private: bool, now: Optional[datetime] = None,
                           snap: Optional[list] = None, until: Optional[datetime] = None):
    """(embed, signature, picture or None) for /live: the picture when something is in play, text otherwise."""
    now = now or datetime.now(timezone.utc)
    snap = snap if snap is not None else await lv_snapshot(gid, now, deep=True)
    embed, sig = await lv_live_embed(client, gid, scope, uid, private, now, snap=snap, until=until)
    try:
        data = await lv2_board_data(client, gid, scope, uid, private, now, snap)
    except Exception:
        log.warning("Live board data failed", exc_info=True)
        data = None
    if data is None:
        return embed, sig, None
    try:
        png = await asyncio.to_thread(locked_render, render_live_board, data)
    except Exception:
        log.warning("Live board render failed", exc_info=True)
        return embed, sig, None
    lines = []
    for g in data["games"]:
        c = lv_counts(g["rows"])
        bits = " · ".join(f"{LV_ICON[k]} {c[k]}" for k in ("cleared", "close", "live", "ahead", "behind", "dead") if c.get(k))
        sc = lambda t: f" {t['score']:g}" if t.get("score") is not None else ""
        lines.append(f"**{lv_abbr(g['away'])}{sc(g['away'])} · {lv_abbr(g['home'])}{sc(g['home'])}** · {clip(g['status'], 24)} · "
                     f"{len(g['rows'])} leg{'s' if len(g['rows']) != 1 else ''}" + (f" · {bits}" if bits else ""))
    if data["tonight"]:
        lines.append("⏰ Later: " + " · ".join(f"{t} {name}" for t, name, _ in data["tonight"]))
    embed.description = clip("\n".join(lines), 4000)
    f, name = await lv2_animated(png, "live")
    embed.set_image(url=f"attachment://{name}")
    return embed, sig, f


# ---- /gamecard: the game tracker card for any game, on demand ------------------------------------------------

def lv2_card_games(gid: int, snap: list[dict], now: datetime, uid: int) -> list[dict]:
    """Games the group has legs on: live first, then later today, then tonight's finals."""
    vis = [s for s in snap if s["public"]]         # the card is posted in the channel: hidden slips stay out
    games = list(lv_games_of(vis).values())
    start_of = lambda g: event_time(g["ev"]) or now
    _, end = lv_night_bounds(lv_night(now))
    keep = [g for g in games if g["ev"].get("state") == "in"
            or (g["ev"].get("state") == "pre" and start_of(g) <= end + timedelta(hours=12))
            or ((g["ev"].get("final") or g["ev"].get("state") == "post") and start_of(g) >= now - timedelta(hours=14))]
    order = {"in": 0, "pre": 1, "post": 2}
    keep.sort(key=lambda g: (order.get("post" if g["ev"].get("final") else g["ev"].get("state"), 3), start_of(g)))
    return keep


def lv2_game_label(g: dict) -> str:
    ev = g["ev"]
    n = len(g["rows"])
    state = "Final" if (ev.get("final") or ev.get("state") == "post") else (
        "LIVE " + (ev.get("detail") or "") if ev.get("state") == "in" else lv_status_text(ev))
    return clip(f"{lv_score_line(ev)} · {state} · {n} leg{'s' if n != 1 else ''}", 100)


async def gamecard_autocomplete(interaction: discord.Interaction, current: str) -> list:
    try:
        now = datetime.now(timezone.utc)
        snap = await asyncio.wait_for(lv_snapshot(interaction.guild_id, now), 2.5)
        games = lv2_card_games(interaction.guild_id, snap, now, interaction.user.id)
    except Exception:
        return []
    cur = (current or "").lower()
    out = []
    for g in games:
        label = lv2_game_label(g)
        if cur and cur not in label.lower():
            continue
        out.append(app_commands.Choice(name=label, value=str(g["id"])[:100]))
    return out[:25]


async def gamecard_payload(client, gid: int, uid: int, game: Optional[str], now: Optional[datetime] = None):
    """(embed, file) for one game's card, or (message, None) when there's no such game."""
    now = now or datetime.now(timezone.utc)
    snap = await lv_snapshot(gid, now, deep=True)
    games = lv2_card_games(gid, snap, now, uid)
    if not games:
        return ("No games with the group's legs on them right now or later today. Log a slip and its games show up "
                "here."), None
    g = None
    if game:
        g = next((x for x in games if str(x["id"]) == str(game)), None)
        if g is None:
            q = game.lower()
            g = next((x for x in games if q in lv2_game_label(x).lower()), None)
        if g is None:
            return "I couldn't find that game. Start typing a team and pick it from the list.", None
    else:
        g = games[0]                         # the live game first, else the next one up
    rows = lv2_game_rows(g)
    final = bool(g["ev"].get("final") or g["ev"].get("state") == "post")
    embed, f = await lv_card_payload(client, gid, g["ev"], g["path"], rows, final, now)
    return embed, f


